for n in range(_sage_const_1 , _sage_const_3 *m + _sage_const_2 ):
    plus = prod(_sage_const_2 *m*n + k for k in range(_sage_const_1 , _sage_const_2 *m + _sage_const_1 ))
    minus = prod(_sage_const_2 *m*n - k for k in range(_sage_const_1 , _sage_const_2 *m + _sage_const_1 ))
    P_pos = sum(vars[i] * n**i for i in range(_sage_const_2 *m + _sage_const_1 ))
